 14923              (stcb == NULL))
 14924                  return (m);
 14925
 14926          if (stcb->asoc.auth_supported == 0) {
 14927                  return (m);
 14928          }
 14929          /* does the requested chunk require auth? */
 14930          if (!sctp_auth_is_required_chunk(chunk, stcb->asoc.peer_auth_chunks)) {
 14931                  return (m);
 14932          }
 14933          m_auth = sctp_get_mbuf_for_msg(sizeof(*auth), 0, M_NOWAIT, 1, MT_HEADER);
 14934          if (m_auth == NULL) {
 14935                  /* no mbuf's */
 14936                  return (m);
 14937          }
 14938          /* reserve some space if this will be the first mbuf */
 14939          if (m == NULL)
 14940                  SCTP_BUF_RESV_UF(m_auth, SCTP_MIN_OVERHEAD);
 14941          /* fill in the AUTH chunk details */
 14942          auth = mtod(m_auth, struct sctp_auth_chunk *);
 14943          memset(auth, 0, sizeof(*auth));
 14944          auth->ch.chunk_type = SCTP_AUTHENTICATION;
 14945          auth->ch.chunk_flags = 0;
 14946          chunk_len = sizeof(*auth) +
 14947              sctp_get_hmac_digest_len(stcb->asoc.peer_hmac_id);
 14948          auth->ch.chunk_length = htons(chunk_len);
 14949          auth->hmac_id = htons(stcb->asoc.peer_hmac_id);
 14950          /* key id and hmac digest will be computed and filled in upon send */
 14951
 14952          /* save the offset where the auth was inserted into the chain */
